                    $lead_log->reference_person_id = $lead->reference_person_id;
                    $lead_log->updated_by = $lead->sale_person_id;
                    $lead_log->save();

                    $lead->status_id = 12;
                    $lead->updated_by = $lead->sale_person_id;
                    $lead->save();

                    $user->lead_id = $lead->id;
                    $user->save();

                }
            }
        }
    }
}
